5	// Edge length of a square thread-block tile. Each block cooperatively loads a
6	// TILE x TILE sub-block of A and B into shared memory, multiplies them, and
7	// accumulates into the corresponding tile of C.
8	#define TILE 16
9	
10	// Classic shared-memory tiled matrix multiply. The kernel is written to handle
11	// matrices whose dimensions are not a multiple of TILE: every global load is
12	// guarded so out-of-range elements read as zero, and the final store is masked
13	// by `row < N && col < N`.
14	__global__ void gemmKernel(const float* A, const float* B, float* C, int N) {
15	    __shared__ float As[TILE][TILE];
16	    __shared__ float Bs[TILE][TILE];
17	
18	    const int row = blockIdx.y * TILE + threadIdx.y;
19	    const int col = blockIdx.x * TILE + threadIdx.x;
20	    const int numTiles = (N + TILE - 1) / TILE;
21	
22	    float acc = 0.0f;
23	    for (int t = 0; t < numTiles; ++t) {
24	        const int aCol = t * TILE + threadIdx.x;
25	        const int bRow = t * TILE + threadIdx.y;
26	
27	        As[threadIdx.y][threadIdx.x] =
28	            (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
29	        Bs[threadIdx.y][threadIdx.x] =
30	            (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;
31	        __syncthreads();
32	
33	#pragma unroll
34	        for (int k = 0; k < TILE; ++k)
35	            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
36	        __syncthreads();
37	    }
38	
39	    if (row < N && col < N)
40	        C[row * N + col] = acc;
41	}
