51	static void runGpu(const std::vector<float>& hA, const std::vector<float>& hB,
52	                   std::vector<float>& hC, int N) {
53	    const size_t bytes = (size_t)N * N * sizeof(float);
54	    float *dA, *dB, *dC;
55	    CUDA_CHECK(cudaMalloc(&dA, bytes));
56	    CUDA_CHECK(cudaMalloc(&dB, bytes));
57	    CUDA_CHECK(cudaMalloc(&dC, bytes));
58	    CUDA_CHECK(cudaMemcpy(dA, hA.data(), bytes, cudaMemcpyHostToDevice));
59	    CUDA_CHECK(cudaMemcpy(dB, hB.data(), bytes, cudaMemcpyHostToDevice));
60	    CUDA_CHECK(cudaMemset(dC, 0, bytes));  // unwritten entries read back as 0
61	
62	    launchGemm(dA, dB, dC, N);
63	    CUDA_CHECK(cudaGetLastError());
64	    CUDA_CHECK(cudaDeviceSynchronize());
65	
66	    CUDA_CHECK(cudaMemcpy(hC.data(), dC, bytes, cudaMemcpyDeviceToHost));
67	    cudaFree(dA);
68	    cudaFree(dB);
69	    cudaFree(dC);
70	}
