#include <cuda_runtime.h>

// ---------------------------------------------------------------------------
// Optimised tiled single-precision GEMM for Ampere (sm_86)
//
// Block layout: 16 × 16 threads = 256 threads
//   – each thread accumulates 2×2 output elements (register tiling)
//   – output tile per block: 32 × 32
//   – K tile size: 16
//
// Shared memory tiles with 1-column / 1-row padding to avoid bank conflicts:
//   As[32][17] – 32 output rows, 17 cols (1 pad)
//   Bs[17][32] – 17 K rows, 32 output cols
//
// Coalesced global loads: within each warp, threads read consecutive columns
// from the same row → one cache line per row.
//
// Pipelined loading: tile t+1 is loaded while tile t is being computed.
// Only one __syncthreads() per tile (after load), no sync after compute.
// ---------------------------------------------------------------------------

static constexpr int BX = 16;
static constexpr int BY = 16;
static constexpr int RM = 2;
static constexpr int RN = 2;
static constexpr int K  = 16;

static constexpr int OM = BY * RM;   // 32  output rows per block
static constexpr int ON = BX * RN;   // 32  output cols per block

__shared__ float As[OM][K + 1];   // 32 × 17  (1-column padding)
__shared__ float Bs[K + 1][ON];   // 17 × 32

__global__ void __launch_bounds__(256, 8)
gemmKernel(const float* __restrict__ A,
           const float* __restrict__ B,
           float* __restrict__ C,
           int N)
{
    // Tile coordinates in the output matrix
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;       // number of K-tiles

    // Output row / col indices that this thread is responsible for
    const int r0 = br + threadIdx.y;       // 0..31
    const int r1 = r0 + BY;                // 16..47  (second row of the 2)
    const int c0 = bc + threadIdx.x * RN;  // 0..30
    const int c1 = c0 + RN - 1;            // 1..31

    float a00 = 0.0f, a01 = 0.0f;
    float a10 = 0.0f, a11 = 0.0f;

    // ── Load tile 0 (before the loop) ──────────────────────────────────
    {
        int c = threadIdx.x;
        int r = threadIdx.y;
        As[threadIdx.y][threadIdx.x] =
            (r0 < N && c < N) ? A[r0 * N + c] : 0.0f;
        As[threadIdx.y + BY][threadIdx.x] =
            (r1 < N && c < N) ? A[r1 * N + c] : 0.0f;
        Bs[threadIdx.y][threadIdx.x * RN] =
            (r < N && c0 < N) ? B[r * N + c0] : 0.0f;
        Bs[threadIdx.y][threadIdx.x * RN + 1] =
            (r < N && c1 < N) ? B[r * N + c1] : 0.0f;
    }
    __syncthreads();

    for (int t = 0; t < nt; ++t) {
        // ── Compute tile t ─────────────────────────────────────────────
        #pragma unroll
        for (int k = 0; k < K; ++k) {
            register float ar0 = As[threadIdx.y][k];
            register float ar1 = As[threadIdx.y + BY][k];
            register float br0 = Bs[k][threadIdx.x * RN];
            register float br1 = Bs[k][threadIdx.x * RN + 1];
            a00 += ar0 * br0;
            a01 += ar0 * br1;
            a10 += ar1 * br0;
            a11 += ar1 * br1;
        }

        // ── Load tile t+1 (pipeline: overlap with the next compute) ─────
        if (t + 1 < nt) {
            int c = (t + 1) * K + threadIdx.x;
            int r = (t + 1) * K + threadIdx.y;
            As[threadIdx.y][threadIdx.x] =
                (r0 < N && c < N) ? A[r0 * N + c] : 0.0f;
            As[threadIdx.y + BY][threadIdx.x] =
                (r1 < N && c < N) ? A[r1 * N + c] : 0.0f;
            Bs[threadIdx.y][threadIdx.x * RN] =
                (r < N && c0 < N) ? B[r * N + c0] : 0.0f;
            Bs[threadIdx.y][threadIdx.x * RN + 1] =
                (r < N && c1 < N) ? B[r * N + c1] : 0.0f;
            __syncthreads();
        }
    }

    // ── Store results ──────────────────────────────────────────────────
    C[r0 * N + c0] = a00;
    C[r0 * N + c1] = a01;
    C[r1 * N + c0] = a10;
    C[r1 * N + c1] = a11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N)
{
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    gemmKernel<<<gx, gy>>>(dA, dB, dC, N);
}
"}

