#include <cuda_runtime.h>

// 16×16 thread block, each thread computes 2×2 output elements
// Output tile per block: 32 × 32
// Shared memory: As[32][16], Bs[16][32] — K tile is 16×16

#define BX 16
#define BY 16
#define K 16

static const int OM = BY * 2;  // 32 output rows per block
static const int ON = BX * 2;  // 32 output cols per block

__shared__ float As[OM][K];   // 32 × 16
__shared__ float Bs[K][ON];   // 16 × 32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;   // 0..15
    const int tx = threadIdx.x;   // 0..15

    // Output elements this thread produces:
    //   (br+ty,       bc+2*tx),       (br+ty,       bc+2*tx+1)
    //   (br+ty+16,    bc+2*tx),       (br+ty+16,    bc+2*tx+1)
    const int r0 = br + ty;
    const int r1 = br + ty + 16;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // ── Load shared tile ─────────────────────────────────────────────
        // As: thread (ty,tx) loads rows ty and ty+16 at column tx
        As[ty][tx] = (r0 < N && kOff + tx < N) ? A[r0 * N + kOff + tx] : 0.0f;
        As[ty + 16][tx] = (r1 < N && kOff + tx < N) ? A[r1 * N + kOff + tx] : 0.0f;
        // Bs: thread (ty,tx) loads row ty at columns 2*tx and 2*tx+1
        Bs[ty][tx * 2] = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[ty][tx * 2 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;
        __syncthreads();

        // ── Compute ──────────────────────────────────────────────────────
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            register float ar0 = As[ty][k];
            register float ar1 = As[ty + 16][k];
            register float br0 = Bs[k][tx * 2];
            register float br1 = Bs[k][tx * 2 + 1];
            s00 += ar0 * br0;
            s01 += ar0 * br1;
            s10 += ar1 * br0;
            s11 += ar1 * br1;
        }

        __syncthreads();
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    gemmKernel<<<gx, gy>>>(dA, dB, dC, N);
}
