{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// Block: 16x16 threads, each computes 2x2 output elements
// Output tile per block: 32x32
// Shared memory tiles: As[32][16], Bs[16][32]

#define BX 16
#define BY 16
#define K 16

static const int OM = BY * 2;  // 32
static const int ON = BX * 2;  // 32

__shared__ float As[OM][K];   // 32x16
__shared__ float Bs[K][ON];   // 16x32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    // This thread computes 4 output elements:
    const int r0 = br + ty;
    const int r1 = br + ty + BY;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    // Load shared tile 0
    As[ty][tx] = (r0 < N && tx < N) ? A[r0 * N + tx] : 0.0f;
    As[ty + BY][tx] = (r1 < N && tx < N) ? A[r1 * N + tx] : 0.0f;
    Bs[ty][tx * 2] = (ty < N && c0 < N) ? B[ty * N + c0] : 0.0f;
    Bs[ty][tx * 2 + 1] = (ty < N && c1 < N) ? B[ty * N + c1] : 0.0f;
    __syncthreads();

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // Compute
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            float ar0 = As[ty][k];
            float ar1 = As[ty + BY][k];
            float br0 = Bs[k][tx * 2];
            float br1 = Bs[k][tx * 2 + 1];
            s00 += ar0 * br0;
            s01 += ar0 * br1;
            s10 += ar1 * br0;
            s11 += ar1 * br1;
        }

        // Load next tile
        if (t + 1 < nt) {
            int kNext = (t + 1) * K;
            As[ty][tx] = (r0 < N && kNext + tx < N) ? A[r0 * N + kNext + tx] : 0.0f;
            As[ty + BY][tx] = (r1 < N && kNext + tx < N) ? A[r1 * N + kNext + tx] : 0.0f;
            Bs[ty][tx * 2] = (kNext + ty < N && c0 < N) ? B[(kNext + ty) * N + c0] : 0.0f;
            Bs[ty][tx * 2 + 1] = (kNext + ty < N && c1 < N) ? B[(kNext + ty) * N + c1] : 0.0f;
            __syncthreads();
        }
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    gemmKernel<<<gx, gy>>>(dA, dB, dC, N);
}
