#include <cuda_runtime.h>

// 16x16 thread block, each thread computes 2x2 output elements
// Shared memory: As[32][16] with 1-col padding, Bs[16][32] with 1-row padding

#define K 16
#define OM 32
#define ON 32

__shared__ float As[OM][K + 1];
__shared__ float Bs[K + 1][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;   // 0..15
    const int tx = threadIdx.x;   // 0..15

    // This thread computes 4 output elements:
    const int r0 = br + ty;
    const int r1 = br + ty + 16;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    // Each thread loads 2 rows from As and 2 cols from Bs
    // Use __syncthreads to ensure all loads complete before compute

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // Load As rows: thread (ty,tx) loads As[ty][tx] and As[ty+16][tx]
        // Then syncthreads ensures all 32 rows (0..15 by threads 0..15, 16..31 by threads 0..15)
        As[ty][tx] = (r0 < N && kOff + tx < N) ? A[r0 * N + kOff + tx] : 0.0f;
        As[ty + 16][tx] = (r1 < N && kOff + tx < N) ? A[r1 * N + kOff + tx] : 0.0f;
        // Load Bs cols: thread (ty,tx) loads Bs[ty][tx*2] and Bs[ty][tx*2+1]
        Bs[ty][tx * 2] = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[ty][tx * 2 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;
        __syncthreads();

        // Compute 2x2
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            float ar0 = As[ty][k];
            float ar1 = As[ty + 16][k];
            float br0 = Bs[k][tx * 2];
            float br1 = Bs[k][tx * 2 + 1];
            s00 += ar0 * br0;
            s01 += ar0 * br1;
            s10 += ar1 * br0;
            s11 += ar1 * br1;
        }

        __syncthreads();
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    gemmKernel<<<gx, gy>>>(dA, dB, dC, N);
}
