// Block: 16x16 threads, each computes 2x2 output elements.
// Output tile per block: 32x32. Shared memory: As[32][16], Bs[16][32].
// Each thread handles 4 elements across 2 rows x 2 cols in the output.

#define K 16
#define OM 32  // output rows per block
#define ON 32  // output cols per block

__shared__ float As[OM][K];
__shared__ float Bs[K][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;   // 0..15
    const int tx = threadIdx.x;   // 0..15

    // 4 output elements: (r0,c0), (r0,c1), (r1,c0), (r1,c1)
    const int r0 = br + ty;
    const int r1 = br + ty + 16;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // Load As rows for this thread's 2 output rows
        As[ty][tx] = (r0 < N && kOff + tx < N) ? A[r0 * N + kOff + tx] : 0.0f;
        As[ty + 16][tx] = (r1 < N && kOff + tx < N) ? A[r1 * N + kOff + tx] : 0.0f;

        // Load Bs cols for this thread's 2 output cols
        Bs[ty][tx * 2] = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[ty][tx * 2 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;

        __syncthreads();

        // Accumulate 2x2 results
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            register float ar0 = As[ty][k];
            register float ar1 = As[ty + 16][k];
            register float br0 = Bs[k][tx * 2];
            register float br1 = Bs[k][tx * 2 + 1];
            s00 += ar0 * br0;
            s01 += ar0 * br1;
            s10 += ar1 * br0;
            s11 += ar1 * br1;
        }

        __syncthreads();
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

