#define OM 32
#define ON 32

__shared__ float As[OM][K];
__shared__ float Bs[K][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int r0 = br + ty;
    const int r1 = br + ty + 16;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // Load shared tile:
        // As: each thread loads 2 rows (ty, ty+16) x 2 cols (tx, tx+16) = 4 elements
        // Bs: each thread loads 2 rows (ty, ty+16) x 1 col each (tx*2, tx*2+1) = 2 elements
        // Total: 256 * 6 = 1536, but As=1024, Bs=1024 => need more coverage
        // As[32][32]: 16 threads in y * 2 rows + 16 threads in x * 2 cols => OK (4*256=1024)
        // Bs[32][32]: 16 threads * 1 col + 32 threads per col * 2 cols = OK (2*256=512)... not right

        // Fix: each thread loads As rows ty and ty+16, ALL 32 columns split across x
        // Actually let me use a simpler scheme where threads are mapped 1:1 to output elements

        __syncthreads();

        // Compute 2x2
        #pragma unroll 32
        for (int k = 0; k < K; ++k) {
            s00 += As[ty][k] * Bs[k][tx * 2];
            s01 += As[ty][k] * Bs[k][tx * 2 + 1];
            s10 += As[ty + 16][k] * Bs[k][tx * 2];
            s11 += As[ty + 16][k] * Bs[k][tx * 2 + 1];
        }

        __syncthreads();
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
