        int kOff = t * K;

        // Load: thread loads 1 row of As (row r, cols tx*4..tx*4+3)
        // and 4 cols of Bs (rows kOff..kOff+31, col tx*4..tx*4+3)
        As[ty][tx * 4]     = (r < N && kOff + tx * 4 < N) ? A[r * N + kOff + tx * 4] : 0.0f;
        As[ty][tx * 4 + 1] = (r < N && kOff + tx * 4 + 1 < N) ? A[r * N + kOff + tx * 4 + 1] : 0.0f;
        As[ty][tx * 4 + 2] = (r < N && kOff + tx * 4 + 2 < N) ? A[r * N + kOff + tx * 4 + 2] : 0.0f;
        As[ty][tx * 4 + 3] = (r < N && kOff + tx * 4 + 3 < N) ? A[r * N + kOff + tx * 4 + 3] : 0.0f;
        Bs[ty][tx * 4]     = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[ty][tx * 4 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;
        Bs[ty][tx * 4 + 2] = (kOff + ty < N && c2 < N) ? B[(kOff + ty) * N + c2] : 0.0f;
        Bs[ty][tx * 4 + 3] = (kOff + ty < N && c3 < N) ? B[(kOff + ty) * N + c3] : 0.0f;
        __syncthreads();

        // Compute: 4 columns
        #pragma unroll 32
        for (int k = 0; k < K; ++k) {
            float a = As[ty][k];
            s0 += a * Bs[k][tx * 4];
            s1 += a * Bs[k][tx * 4 + 1];
            s2 += a * Bs[k][tx * 4 + 2];
            s3 += a * Bs[k][tx * 4 + 3];
        }

        __syncthreads();
    }

    if (r < N && c0 < N) C[r * N + c0] = s0;
    if (r < N && c1 < N) C[r * N + c1] = s1;
    if (r < N && c2 < N) C[r * N + c2] = s2;
    if (r < N && c3 < N) C[r * N + c3] = s3;
}

