// Block: 32x8 = 256 threads
// Each thread computes 1 row x 4 cols (4 accumulators)
// Output tile: 32x32 (32 rows * 8 warps in Y, 4 cols per thread * 8 threads in X)
// Shared: As[32][32], Bs[32][32]
// tx=0..31 (row dim), ty=0..7 (col dim)

#define K 32
#define OM 32
#define ON 32

__shared__ float As[OM][K];
__shared__ float Bs[K][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int tx = threadIdx.x;   // 0..31  (row in block)
    const int ty = threadIdx.y;   // 0..7   (col group in block)

    // This thread handles row (br+tx) and cols (bc+ty*4 .. bc+ty*4+3)
    const int r = br + tx;
    const int c0 = bc + ty * 4;
    const int c1 = bc + ty * 4 + 1;
    const int c2 = bc + ty * 4 + 2;
    const int c3 = bc + ty * 4 + 3;

    float s0 = 0.0f, s1 = 0.0f, s2 = 0.0f, s3 = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // Load: thread loads As[row][kOff+k] for k=0..31 (entire row)
        //       and Bs[kOff+k][col] for each of its 4 cols
        // tx=0..31, so consecutive threads access consecutive columns → coalesced
        As[tx][ty] = (r < N && kOff + ty < N) ? A[r * N + kOff + ty] : 0.0f;
        Bs[ty][tx * 4]     = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[ty][tx * 4 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;
        Bs[ty][tx * 4 + 2] = (kOff + ty < N && c2 < N) ? B[(kOff + ty) * N + c2] : 0.0f;
        Bs[ty][tx * 4 + 3] = (kOff + ty < N && c3 < N) ? B[(kOff + ty) * N + c3] : 0.0f;
        __syncthreads();

        // Compute 4 cols
        #pragma unroll 32
        for (int k = 0; k < K; ++k) {
            float a = As[tx][k];
            s0 += a * Bs[k][tx * 4];
            s1 += a * Bs[k][tx * 4 + 1];
            s2 += a * Bs[k][tx * 4 + 2];
            s3 += a * Bs[k][tx * 4 + 3];
        }

        __syncthreads();
    }

    if (r < N && c0 < N) C[r * N + c0] = s0;
    if (r < N && c1 < N) C[r * N + c1] = s1;
    if (r < N && c2 < N) C[r * N + c2] = s2;
    if (r < N && c3 < N) C[r * N + c3] = s3;
}

