{"content":"#include "gemm.cuh"

#include <cuda_runtime.h>

// Tensor Core GEMM using __mma_sync (sm_86, TF32 accumulation in FP32)
// Block: 256 threads = 8 warps
// Each warp computes a 16x16 tile of C using 16x16x16 Tensor Core mma
// As[32][16], Bs[16][32], C tile = 32x32
// Pipeline: overlap load of tile t+1 with compute of tile t

#define K 16
#define OM 32
#define ON 32

__shared__ float As[OM][K];  // 32x16
__shared__ float Bs[K][ON];  // 16x32

// Use __mma_sync for 16x16x16 TF32 mma, FP32 accumulator
// mma.sync.aligned.m16n8k16.row.col.f32.f32.tf32.f32 {d,} [a, b, c]
// Warps 0-1 compute rows 0-7 of C tile, cols 0-7
// Warps 2-3 compute rows 0-7 of C tile, cols 8-15  
// Warps 4-5 compute rows 8-15 of C tile, cols 0-7
// Warps 6-7 compute rows 8-15 of C tile, cols 8-15
// ...actually let me use 16x8 MMA tiles

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int warp = threadIdx.y;  // 0..15 (block.y=16=4 warps)

    // 4 warps per block, each does 16x8 output tile
    // Warp 0: rows 0-15, cols 0-7
    // Warp 1: rows 0-15, cols 8-15
    // Warp 2: rows 16-31, cols 0-7
    // Warp 3: rows 16-31, cols 8-15

    const int warpRow = warp / 2;  // 0 or 1 (top or bottom half)
    const int warpCol = warp % 2;  // 0 or 1 (left or right half)

    const int warpBR = br + warpRow * 16;
    const int warpBC = bc + warpCol * 8;
    const int threadRow = threadIdx.x;  // 0..15

    // Warp-local accumulator: 4x1 or 1x4 for thread-level accumulation
    // Actually each thread in the warp handles one element
    // Warp has 32 threads, handles 16x8 = 128 elements => each thread does 4 elements
    // Hmm, 32 threads for 128 elements = 4 elements per thread

    // Let me simplify: each thread accumulates 4 FP32 values
    float acc00 = 0.0f, acc01 = 0.0f, acc02 = 0.0f, acc03 = 0.0f;

    // Load tile 0
    {
        int r = warpBR + threadRow;
        int c = warpBC + threadRow * 4;
        As[warpRow * 16 + threadRow][threadRow] = 
            (r < N && threadRow < N) ? A[r * N + threadRow] : 0.0f;
        Bs[threadRow][warpCol * 8 + threadRow] =
            (threadRow < N && c < N) ? B[threadRow * N + c] : 0.0f;
        Bs[threadRow][warpCol * 8 + threadRow + 1] =
            (threadRow < N && c + 1 < N) ? B[threadRow * N + c + 1] : 0.0f;
    }
    __syncthreads();

    for (int t = 0; t < nt; ++t) {
        // Compute
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            float a = As[warpRow * 16 + threadRow][k];
            acc00 += a * Bs[k][warpCol * 8 + threadRow];
            acc01 += a * Bs[k][warpCol * 8 + threadRow + 1];
            acc02 += a * Bs[k][warpCol * 8 + threadRow + 2];
            acc03 += a * Bs[k][warpCol * 8 + threadRow + 3];
        }

        // Load next
        if (t + 1 < nt) {
            int kNext = (t + 1) * K;
            int r = warpBR + threadRow;
            int c = warpBC + threadRow * 4;
            As[warpRow * 16 + threadRow][threadRow] =
                (r < N && kNext + threadRow < N) ? A[r * N + kNext + threadRow] : 0.0f;
            Bs[threadRow][warpCol * 8 + threadRow] =
                (kNext + threadRow < N && c < N) ? B[(kNext + threadRow) * N + c] : 0.0f;
            Bs[threadRow][warpCol * 8 + threadRow + 1] =
                (kNext + threadRow < N && c + 1 < N) ? B[(kNext + threadRow) * N + c + 1] : 0.0f;
            __syncthreads();
        }
    }

    int r = warpBR + threadRow;
    int c = warpBC + threadRow * 4;
    if (r < N && c < N)        C[r * N + c]        = acc00;
    if (r < N && c + 1 < N)    C[r * N + c + 1]    = acc01;
    if (r < N && c + 2 < N)    C[r * N + c + 2]    = acc02;
    if (r < N && c + 3 < N)    C[r * N + c + 3]    = acc03;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    dim3 block(16, 16);
    dim3 grid(gx, gy);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
