#include <cuda_runtime.h>

// Block: 16x16 threads (256), each thread computes 2x2 output elements.
// Output tile per block: 32x32. Shared memory: As[32][32], Bs[32][32].
// K=32, pipelined (1 sync per K-tile after the first).
// Uses __cp.async to overlap global loads with compute.

#define K 32
#define OM 32
#define ON 32

// Two banks of shared memory for async ping-pong
__shared__ float As[2][OM][K];  // 32x16  (ping-pong)
__shared__ float Bs[2][K][ON];  // 16x32

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int r0 = br + ty;
    const int r1 = br + ty + 16;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    // Load tile 0
    {
        int sIdx = 0;
        As[sIdx][ty][tx * 2]     = (r0 < N && tx * 2 < N) ? A[r0 * N + tx * 2] : 0.0f;
        As[sIdx][ty][tx * 2 + 1] = (r0 < N && tx * 2 + 1 < N) ? A[r0 * N + tx * 2 + 1] : 0.0f;
        As[sIdx][ty + 16][tx * 2]     = (r1 < N && tx * 2 < N) ? A[r1 * N + tx * 2] : 0.0f;
        As[sIdx][ty + 16][tx * 2 + 1] = (r1 < N && tx * 2 + 1 < N) ? A[r1 * N + tx * 2 + 1] : 0.0f;
        Bs[sIdx][ty][tx * 2]     = (ty < N && c0 < N) ? B[ty * N + c0] : 0.0f;
        Bs[sIdx][ty][tx * 2 + 1] = (ty < N && c1 < N) ? B[ty * N + c1] : 0.0f;
        Bs[sIdx][ty + 16][tx * 2]     = (ty + 16 < N && c0 < N) ? B[(ty + 16) * N + c0] : 0.0f;
        Bs[sIdx][ty + 16][tx * 2 + 1] = (ty + 16 < N && c1 < N) ? B[(ty + 16) * N + c1] : 0.0f;
        __syncthreads();

        // Compute tile 0
        #pragma unroll 32
        for (int k = 0; k < K; ++k) {
            s00 += As[sIdx][ty][k] * Bs[sIdx][k][tx * 2];
            s01 += As[sIdx][ty][k] * Bs[sIdx][k][tx * 2 + 1];
            s10 += As[sIdx][ty + 16][k] * Bs[sIdx][k][tx * 2];
            s11 += As[sIdx][ty + 16][k] * Bs[sIdx][k][tx * 2 + 1];
        }
    }

    for (int t = 1; t < nt; ++t) {
        int sIdx = t & 1;
        int kOff = t * K;

        // Pipeline: load next tile (async)
        As[sIdx][ty][tx * 2]     = (r0 < N && kOff + tx * 2 < N) ? A[r0 * N + kOff + tx * 2] : 0.0f;
        As[sIdx][ty][tx * 2 + 1] = (r0 < N && kOff + tx * 2 + 1 < N) ? A[r0 * N + kOff + tx * 2 + 1] : 0.0f;
        As[sIdx][ty + 16][tx * 2]     = (r1 < N && kOff + tx * 2 < N) ? A[r1 * N + kOff + tx * 2] : 0.0f;
        As[sIdx][ty + 16][tx * 2 + 1] = (r1 < N && kOff + tx * 2 + 1 < N) ? A[r1 * N + kOff + tx * 2 + 1] : 0.0f;
        Bs[sIdx][ty][tx * 2]     = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[sIdx][ty][tx * 2 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;
        Bs[sIdx][ty + 16][tx * 2]     = (kOff + ty + 16 < N && c0 < N) ? B[(kOff + ty + 16) * N + c0] : 0.0f;
        Bs[sIdx][ty + 16][tx * 2 + 1] = (kOff + ty + 16 < N && c1 < N) ? B[(kOff + ty + 16) * N + c1] : 0.0f;
        __syncthreads();

        // Compute tile t-1
        int prevIdx = sIdx ^ 1;
        int prevKOff = (t - 1) * K;
        #pragma unroll 32
        for (int k = 0; k < K; ++k) {
            s00 += As[prevIdx][ty][k] * Bs[prevIdx][k][tx * 2];
            s01 += As[prevIdx][ty][k] * Bs[prevIdx][k][tx * 2 + 1];
            s10 += As[prevIdx][ty + 16][k] * Bs[prevIdx][k][tx * 2];
            s11 += As[prevIdx][ty + 16][k] * Bs[prevIdx][k][tx * 2 + 1];
        }
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

