    const int lane = threadIdx.x;  // 0..31

    // Warp 0-1: top half (rows 0-15), left half (cols 0-15)
    // Warp 2-3: top half (rows 0-15), right half (cols 16-31)
    // Warp 4-5: bottom half (rows 16-31), left half (cols 0-15)
    // Warp 6-7: bottom half (rows 16-31), right half (cols 16-31)

    const int warpRow = warp / 2;  // 0,0,1,1,2,2,3,3
    const int warpCol = warp % 2;  // 0,1,0,1,0,1,0,1

    const int warpBR = br + warpRow * 16;
    const int warpBC = bc + warpCol * 16;

