// Block: 16x16 threads (256), each computes 1x4 output elements.
// Output tile per block: 32x64. Shared memory: As[32][16], Bs[16][64].
// K=16 tiles. Each thread handles 1 row x 4 cols.
// This gives 32x4 = 128 output elements per thread, 256 threads * 4 = 1024 elements
// per block = 32x32 output. Wait, 32 rows x 64 cols = 2048, but 256 threads * 4 = 1024.
// Fix: each thread handles 2 rows x 2 cols = 4 elements. 256 * 4 = 1024 = 32x32.

// Actually let me use a simpler approach: 32x16 block = 512 threads
// Each thread computes 1 row x 2 cols = 2 elements
// Output tile: 32x32 (32 rows, 32 cols)
// 32 rows / 32 thread rows = 1 thread per row
// 32 cols / 2 = 16 thread cols
// Block = 32x16 = 512 threads = 16 warps

#define K 16
#define OM 32
#define ON 32

__shared__ float As[OM][K];
__shared__ float Bs[K][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;   // 0..31
    const int tx = threadIdx.x;   // 0..15

    // Each thread handles 2 rows x 2 cols
    const int r0 = br + ty;
    const int r1 = r0 + 1;  // consecutive row
    const int c0 = bc + tx * 2;
    const int c1 = c0 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    for (int t = 0; t < nt; ++t) {
        int kOff = t * K;

        // Load shared tile
        As[ty][tx * 2]     = (r0 < N && kOff + tx * 2 < N) ? A[r0 * N + kOff + tx * 2] : 0.0f;
        As[ty][tx * 2 + 1] = (r0 < N && kOff + tx * 2 + 1 < N) ? A[r0 * N + kOff + tx * 2 + 1] : 0.0f;
        Bs[ty][tx * 2]     = (kOff + ty < N && c0 < N) ? B[(kOff + ty) * N + c0] : 0.0f;
        Bs[ty][tx * 2 + 1] = (kOff + ty < N && c1 < N) ? B[(kOff + ty) * N + c1] : 0.0f;
        __syncthreads();

        // Compute 2x2
        #pragma unroll 16
        for (int k = 0; k < K; ++k) {
            register float ar0 = As[ty][k];
            register float ar1 = Bs[k][tx * 2];
            s00 += ar0 * ar1;
            s01 += ar0 * Bs[k][tx * 2 + 1];
            s10 += As[ty + 1][k] * ar1;
            s11 += As[ty + 1][k] * Bs[k][tx * 2 + 1];
        }

        __syncthreads();
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

