    int warpRow = warp / 2;
    int warpCol = warp % 2;

    int br = blockIdx.y * OM + warpRow * 16;
    int bc = blockIdx.x * ON + warpCol * 8;

    // Accumulator fragment: 16x8 FP32
    wmma::fragment<wmma::accumulator, 16, 8, 16, float> acc;
    wmma::fill_fragment(acc, 0.0f);

    // WMMA fragments
    wmma::fragment<wmma::matrix_a, 16, 8, 16, half, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, 16, 8, 16, half, wmma::row_major> b_frag;

    int nt = (N + K - 1) / K;

    for (int t = 0; t < nt; ++t) {
