#include <cuda_runtime.h>

// Block: 16x16=256 threads, each computes 2x2 output.
// Output tile: 32x32 per block. Shared: As[32][32], Bs[32][32].
// K=64, pipelined: 1 sync per K-tile.
// Pipeline structure:
//   Load tile 0 before loop
//   For each tile: compute tile t, then load tile t+1, then sync
// This works because we only ever need 1 shared memory tile at a time.

#define K 32
#define OM 32
#define ON 32

__shared__ float As[OM][K];
__shared__ float Bs[K][ON];

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N)
{
    const int br = blockIdx.y * OM;
    const int bc = blockIdx.x * ON;
    const int nt = (N + K - 1) / K;

    const int ty = threadIdx.y;
    const int tx = threadIdx.x;

    const int r0 = br + ty;
    const int r1 = br + ty + 16;
    const int c0 = bc + tx * 2;
    const int c1 = bc + tx * 2 + 1;

    float s00 = 0.0f, s01 = 0.0f;
    float s10 = 0.0f, s11 = 0.0f;

    // Load tile 0
    {
        As[ty][tx * 2]     = (r0 < N && tx * 2 < N) ? A[r0 * N + tx * 2] : 0.0f;
        As[ty][tx * 2 + 1] = (r0 < N && tx * 2 + 1 < N) ? A[r0 * N + tx * 2 + 1] : 0.0f;
        As[ty + 16][tx * 2]     = (r1 < N && tx * 2 < N) ? A[r1 * N + tx * 2] : 0.0f;
        As[ty + 16][tx * 2 + 1] = (r1 < N && tx * 2 + 1 < N) ? A[r1 * N + tx * 2 + 1] : 0.0f;
        Bs[ty][tx * 2]     = (ty < N && c0 < N) ? B[ty * N + c0] : 0.0f;
        Bs[ty][tx * 2 + 1] = (ty < N && c1 < N) ? B[ty * N + c1] : 0.0f;
        Bs[ty + 16][tx * 2]     = (ty + 16 < N && c0 < N) ? B[(ty + 16) * N + c0] : 0.0f;
        Bs[ty + 16][tx * 2 + 1] = (ty + 16 < N && c1 < N) ? B[(ty + 16) * N + c1] : 0.0f;
        __syncthreads();
    }

    for (int t = 0; t < nt; ++t) {
        // Compute tile t
        #pragma unroll 32
        for (int k = 0; k < K; ++k) {
            s00 += As[ty][k] * Bs[k][tx * 2];
            s01 += As[ty][k] * Bs[k][tx * 2 + 1];
            s10 += As[ty + 16][k] * Bs[k][tx * 2];
            s11 += As[ty + 16][k] * Bs[k][tx * 2 + 1];
        }

        // Pipeline: load next tile
        if (t + 1 < nt) {
            int kNext = (t + 1) * K;
            As[ty][tx * 2]     = (r0 < N && kNext + tx * 2 < N) ? A[r0 * N + kNext + tx * 2] : 0.0f;
            As[ty][tx * 2 + 1] = (r0 < N && kNext + tx * 2 + 1 < N) ? A[r0 * N + kNext + tx * 2 + 1] : 0.0f;
            As[ty + 16][tx * 2]     = (r1 < N && kNext + tx * 2 < N) ? A[r1 * N + kNext + tx * 2] : 0.0f;
            As[ty + 16][tx * 2 + 1] = (r1 < N && kNext + tx * 2 + 1 < N) ? A[r1 * N + kNext + tx * 2 + 1] : 0.0f;
            Bs[ty][tx * 2]     = (kNext + ty < N && c0 < N) ? B[(kNext + ty) * N + c0] : 0.0f;
            Bs[ty][tx * 2 + 1] = (kNext + ty < N && c1 < N) ? B[(kNext + ty) * N + c1] : 0.0f;
            Bs[ty + 16][tx * 2]     = (kNext + ty + 16 < N && c0 < N) ? B[(kNext + ty + 16) * N + c0] : 0.0f;
            Bs[ty + 16][tx * 2 + 1] = (kNext + ty + 16 < N && c1 < N) ? B[(kNext + ty + 16) * N + c1] : 0.0f;
            __syncthreads();
        }
    }

    if (r0 < N && c0 < N) C[r0 * N + c0] = s00;
    if (r0 < N && c1 < N) C[r0 * N + c1] = s01;
    if (r1 < N && c0 < N) C[r1 * N + c0] = s10;
    if (r1 < N && c1 < N) C[r1 * N + c1] = s11;
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    int gx = (N + ON - 1) / ON;
    int gy = (N + OM - 1) / OM;
    dim3 block(16, 16);
    dim3 grid(gx, gy);
    gemmKernel<<<grid, block>>>(dA, dB, dC, N);
}
